import Handlebars from 'handlebars';
import coalesce from '../helper/string/coalesce.js';

Handlebars.registerHelper('coalesce', coalesce);

describe('coalesce helper', () => {

  // Тест для повернення першого непорожнього значення
  it('should return the first non-null value', () => {
    const template = Handlebars.compile('{{coalesce null undefined "" 42}}');
    const result = template({});
    expect(result).toBe('42');
  });

  // Тест для повернення першого непорожнього рядка
  it('should return the first non-empty string', () => {
    const template = Handlebars.compile('{{coalesce "" "valid" "backup"}}');
    const result = template({});
    expect(result).toBe('valid');
  });

  // Тест для використання числа
  it('should return the first number', () => {
    const template = Handlebars.compile('{{coalesce null "" 0 123}}');
    const result = template({});
    expect(result).toBe('0'); // 0 є дійсним значенням
  });


});
